use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm::{self, Reply};

struct Node;

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        // `requires len(question) <= 512` holds of every input, so the body does
        // not re-check it. We simply answer from the node's granted authority:
        // the `lookup` tool (via tool-llm) and the read-only knowledge base.

        let system = "You are a customer support agent. Answer the user's \
                      question. If you need facts you do not have, request the \
                      `lookup` tool with a concise query; otherwise answer directly.";

        let mut prompt = String::new();
        prompt.push_str("Question: ");
        prompt.push_str(&ctx.question);

        if !ctx.knowledge.is_empty() {
            prompt.push_str("\n\nKnown context:\n");
            for k in &ctx.knowledge {
                prompt.push_str("- ");
                prompt.push_str(k);
                prompt.push('\n');
            }
        }

        // Bounded tool-orchestration loop: the model either answers, or asks for
        // a tool. We invoke only `lookup`, the one tool in this node's scope.
        let mut rounds: u32 = 0;
        loop {
            match tool_llm::generate(&system_with_intent(system, ctx.intent), &prompt) {
                Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                Reply::Call(req) => {
                    rounds += 1;
                    if rounds > 4 {
                        return ResponseResult::Error(LlmError {
                            message: "tool orchestration did not converge".to_string(),
                        });
                    }

                    if req.tool == "lookup" {
                        let results = kb_read::lookup(&req.query);
                        prompt.push_str("\n\nlookup(\"");
                        prompt.push_str(&req.query);
                        prompt.push_str("\") returned:\n");
                        if results.is_empty() {
                            prompt.push_str("(no matches)\n");
                        } else {
                            for r in &results {
                                prompt.push_str("- ");
                                prompt.push_str(r);
                                prompt.push('\n');
                            }
                        }
                    } else {
                        // Any other tool is outside this node's authority. We do
                        // not invoke it; we tell the model it is unavailable and
                        // let it answer without it.
                        prompt.push_str("\n\nTool `");
                        prompt.push_str(&req.tool);
                        prompt.push_str("` is not available; answer without it.\n");
                    }
                }
            }
        }
    }
}

fn system_with_intent(base: &str, intent: Intent) -> String {
    let label = match intent {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    };
    let mut s = String::with_capacity(base.len() + label.len() + 24);
    s.push_str(base);
    s.push_str("\nClassified intent: ");
    s.push_str(label);
    s
}

export!(Node);
